<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Accessor\MessageContentAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the MessageContentAccessor trait.
 *
 * Covers null default, string/VO assignment via withContent,
 * getContent/content accessors, and isContentChanged with/without original.
 */
class MessageContentAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withContent creates a new instance with the Content set
     * from a string value, and getContent returns the primitive string.
     */
    public function testWithContentFromString(): void
    {
        // Arrange
        $holder = new ImplWithMessageContentAccessorUnitTest();

        // Act
        $result = $holder->withContent('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getContent());
    }
    /**
     * Asserts that withcontent has access to the value object
     * from a string value, and getContent returns the primitive string.
     */
    public function testWithContentFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithMessageContentAccessorUnitTest();

        // Act
        $result = $holder->withContent('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->content()->value());
    }
    public function testChangedContent(): void
    {
        // Arrange
        $holder = new ImplWithMessageContentAccessorUnitTest()->withContent('one');
        $original = $holder->withContent('one');
        $same = $holder->withContent('one');
        $modified = $holder->withContent('other');

        // Act
        $withSame = $original->isContentChanged($same);
        $withDiferent = $original->isContentChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithMessageContentAccessorUnitTest
{
    use MessageContentAccessor;
}
